import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.mockito.Mockito.when;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

@ExtendWith(MockitoExtension.class)
class DiscountServiceTest {

    @Mock
    private PriceRepository priceRepository;

    @InjectMocks
    private DiscountService discountService;

    @Test
    void tenPercentDiscountApplied() {
        when(priceRepository.findPrice("BOOK")).thenReturn(100.0);
        assertEquals(90.0, discountService.discountedPrice("BOOK", 10), 0.001);
    }

    @Test
    void invalidPercentThrows() {
        assertThrows(IllegalArgumentException.class,
            () -> discountService.discountedPrice("BOOK", 150));
    }
}

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;
import java.time.Clock;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import org.junit.jupiter.api.Test;

class SubscriptionServiceTest {

    private static final Clock FIXED_CLOCK =
        Clock.fixed(Instant.parse("2026-11-04T00:00:00Z"), ZoneId.of("UTC"));

    @Test
    void expiryCheckedAgainstInjectedClock() {
        SubscriptionService service = new SubscriptionService(FIXED_CLOCK);
        assertFalse(service.isExpired(LocalDate.parse("2026-11-04")));
        assertTrue(service.isExpired(LocalDate.parse("2026-11-03")));
    }
}

import static org.mockito.Mockito.when;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.content;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.test.web.servlet.MockMvc;

@WebMvcTest(HelloController.class)
class HelloControllerTest {

    @Autowired
    private MockMvc mockMvc;

    @MockitoBean
    private GreetingService greetingService;

    @Test
    void helloReturnsGreeting() throws Exception {
        when(greetingService.greet("Beanstack")).thenReturn("Hello, Beanstack");
        mockMvc.perform(get("/hello").param("name", "Beanstack"))
            .andExpect(status().isOk())
            .andExpect(content().string("Hello, Beanstack"));
    }

    @Test
    void missingNameParameterIsBadRequest() throws Exception {
        mockMvc.perform(get("/hello"))
            .andExpect(status().isBadRequest());
    }
}
